from PIL import Image
import numpy as np
a=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
# print x runs of saturation at each y 0..45, using r-g and b dark
for y in range(0,45):
 vals=[]
 for x in range(100,160):
  r,g,b=a[y,x]; s=max(r,g,b)-min(r,g,b)
  if s>35 and r>=g: vals.append(x)
 # group
 groups=[]
 for x in vals:
  if not groups or x>groups[-1][-1]+1:groups.append([x])
  else:groups[-1].append(x)
 print(y,[(g[0],g[-1]) for g in groups])
